PlayerPC_Mailbox.body:
gPlayerPCItemPageInfo.count = GetMailboxMailCount();

    if (gPlayerPCItemPageInfo.count == 0)
    {

        DisplayItemMessageOnField(taskId, gText_NoMailHere, ReshowPlayerPC);
