PlayerPC_TurnOff.body:
if (sTopMenuNumOptions == NUM_BEDROOM_PC_OPTIONS)  
    {
        if (gSaveBlock2Ptr->playerGender == MALE)
            ScriptContext_SetupScript(LittlerootTown_BrendansHouse_2F_EventScript_TurnOffPlayerPC);
        else
